        rootAllocator.verify();
        result1.buffer.release();
        result2.buffer.release();
        // releases arrowBuf1
        arrowBuf1s.release();
        // releases arrowBuf2
        arrowBuf2s.release();
        childAllocator1.close();
        childAllocator2.close();
    }
}

